/* Pure view, groups 17/18. No writes, listeners, network, date defaults or diagnosis. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.NutriHealthInsightsGlass=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v.filter(x=>x&&typeof x==='object'):[];
const num=v=>typeof v==='number'&&Number.isFinite(v);
const fmt=v=>num(v)?String(Math.round(v*100)/100):'未知';
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v?v:'日期未知';
const art=Object.freeze({'shrimp-quinoa':'../assets/recipes/shrimp-quinoa-original.png','salmon-rice':'../assets/recipes/salmon-rice-original.png','tofu-soup':'../assets/recipes/tofu-soup-original.png','chicken-grain':'../assets/recipes/chicken-grain-original.png'});
function button(label,action,id,extra=''){return `<button type="button" class="hig-button" data-hd="${esc(action)}"${id===undefined?'':` data-id="${esc(id)}"`}${extra}>${esc(label)}</button>`;}
function card(body,extra=''){return `<section class="hig-card ${extra}">${body}</section>`;}
function shell(title,sub,body){return `<div class="hig-view"><header class="hig-heading"><span class="hig-eyebrow">本机合成演示</span><h2>${esc(title)}</h2><p>${esc(sub)}</p></header>${body}</div>`;}
function note(text){return `<p class="hig-notice">${esc(text)}</p>`;}
function stat(label,value,unit,foot=''){return `<div class="hig-stat"><small>${esc(label)}</small><strong>${esc(value)} <em>${esc(unit)}</em></strong>${foot?`<small>${esc(foot)}</small>`:''}</div>`;}
function definitions(model){return Object.entries(model?.METRICS||{}).filter(([,v])=>v&&typeof v==='object');}
function metricData(health,model,key){const def=definitions(model).find(([k])=>k===key)?.[1];if(!def)return null;const all=arr(health?.metrics).filter(r=>r.metric===key);const rows=all.filter(r=>num(r.value)&&date(r.date)!=='日期未知'&&r.unit===def.unit).slice().sort((a,b)=>a.date.localeCompare(b.date));return {def,all,rows,latest:rows.at(-1)};}
function chart(rows,unit){if(!rows.length)return note('尚无日期、数值和单位完整的记录；未填写不代表 0。');const visible=rows.slice(-14),min=Math.min(...visible.map(r=>r.value)),max=Math.max(...visible.map(r=>r.value)),span=max-min||1;const points=visible.map((r,i)=>[24+(visible.length===1?156:i*312/(visible.length-1)),126-(r.value-min)/span*88]);return `<svg class="hig-chart" viewBox="0 0 360 165" role="img" aria-label="最近 ${visible.length} 条记录，相对范围图；详细数值见下表"><path d="M24 38H336 M24 82H336 M24 126H336" class="hig-gridline"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" class="hig-line"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4"><title>${esc(visible[i].date)}：${fmt(visible[i].value)} ${esc(unit)}</title></circle>`).join('')}<text x="24" y="155">${esc(visible[0].date.slice(5))}</text><text x="336" y="155" text-anchor="end">${esc(visible.at(-1).date.slice(5))}</text></svg><p class="hig-muted">最近 ${visible.length} 条 · 相对数值范围，不是风险刻度。</p>`;}
function renderMetrics({health={},model={},metric='weight'}={}){const defs=definitions(model),key=defs.some(([k])=>k===metric)?metric:defs[0]?.[0],d=metricData(health,model,key);if(!d)return shell('健康指标','未提供指标定义',note('暂时无法显示指标，请由控制器加载当前模型。'));const {def,rows,all,latest}=d;const mean=rows.length?rows.reduce((s,r)=>s+r.value,0)/rows.length:null;return shell('指标趋势报告','仅整理合成输入，不作疾病、风险或疗效判断。',`<div class="hig-tabs" aria-label="选择指标">${defs.map(([k,v])=>button(v.label,'metric-tab',k,` aria-pressed="${k===key}"`)).join('')}</div>`+card(`<div class="hig-section-title"><h3>${esc(def.label)}趋势</h3><small>${esc(def.unit)}</small></div><div class="hig-latest">${stat('最近记录',fmt(latest?.value),def.unit,latest?date(latest.date):'尚无有效记录')}</div>${chart(rows,def.unit)}<div class="hig-stats">${stat('有效记录均值',fmt(mean),def.unit)}${stat('最高',fmt(rows.length?Math.max(...rows.map(r=>r.value)):null),def.unit)}${stat('最低',fmt(rows.length?Math.min(...rows.map(r=>r.value)):null),def.unit)}</div><p class="hig-muted">可绘制 ${rows.length}/${all.length} 条；缺数值、日期或匹配单位的记录不参与计算。</p>`)+card(`<h3>记录明细 · ${all.length} 条</h3>${all.length?`<ul class="hig-list">${all.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).map(r=>`<li><div><strong>${esc(date(r.date))}</strong><small>${esc(r.context||'上下文未填写')}</small><small>${esc(r.source||'来源未填写')} · 合成记录</small></div><span>${fmt(r.value)} ${esc(r.unit||'单位未知')}</span></li>`).join('')}</ul>`:note('暂无指标记录。')}`)+card(`<h3>添加合成指标</h3><form data-form="metric"><div class="hig-fields"><label>指标<select name="metric">${defs.map(([k,v])=>`<option value="${esc(k)}"${k===key?' selected':''}>${esc(v.label)}</option>`).join('')}</select></label><label>日期<input type="date" name="date" value="${date(health.demoDate)==='日期未知'?'':esc(health.demoDate)}" required></label></div><label>数值（按所选指标的单位）<input type="number" name="value" step="any" required></label><p class="hig-muted">${defs.map(([,v])=>esc(v.label)+'：'+esc(v.unit)).join('；')}</p><label>记录上下文<input name="context" maxlength="80" value="合成演示自述" required></label>${note('仅填写合成数据；录入范围不是健康标准。空值不会当作 0。')}<label class="hig-check"><input type="checkbox" name="confirm" required>确认仅保存合成数据到本机</label><button type="submit" class="hig-primary">保存指标</button></form>`));}
function renderConditions({health={},model={},editId}={}){const rows=arr(health.conditions),edit=rows.find(r=>r.id===editId),defs=definitions(model);if(editId&&!edit)return shell('随访自述','记录已不存在',note('请重新选择，不创建替代记录。'));const states=['观察记录','专业人员已告知（演示）','暂停随访'];return shell('慢病与随访','合成自述容器，不是疾病诊断。',card(`<h3>自述记录 · ${rows.length} 条</h3>${rows.length?`<ul class="hig-list">${rows.map(r=>`<li><div><strong>${esc(r.label)}</strong><small>${esc(r.status||'状态未填写')} · ${esc(date(r.date))}</small><small>${(Array.isArray(r.metrics)?r.metrics:[]).map(k=>esc(defs.find(([key])=>key===k)?.[1].label||'未知指标')).join('、')}</small><p>${esc(r.note)}</p></div>${button('编辑','edit-condition',r.id)}</li>`).join('')}</ul>`:note('尚无随访自述，系统不会根据指标创建病名。')}`)+card(`<h3>${edit?'编辑自述':'新增自述'}</h3><form data-form="condition" data-edit-id="${esc(edit?.id||'')}"><label>自述主题<input name="label" value="${esc(edit?.label||'')}" maxlength="80" required></label><label>日期<input name="date" type="date" value="${date(edit?.date||health.demoDate)==='日期未知'?'':esc(edit?.date||health.demoDate)}" required></label><label>自述状态<select name="status">${states.map(s=>`<option${edit?.status===s?' selected':''}>${esc(s)}</option>`).join('')}</select></label><fieldset><legend>随访指标</legend>${defs.map(([k,v])=>`<label class="hig-check"><input type="checkbox" name="metric-${esc(k)}"${Array.isArray(edit?.metrics)&&edit.metrics.includes(k)?' checked':''}>${esc(v.label)}</label>`).join('')}</fieldset><label>补充自述<input name="note" value="${esc(edit?.note||'')}" maxlength="200"></label><label class="hig-check"><input name="confirm" type="checkbox" required>这是合成自述，系统没有作出诊断</label><button class="hig-primary" type="submit">保存自述与随访指标</button></form>`));}
function renderWeekly({health={},model={}}={}){if(date(health.demoDate)==='日期未知'||typeof model.weeklySummary!=='function')return shell('7 日合成回顾','日期或汇总模型未就绪',note('无法确定报告区间，不生成默认日期或示例数值。'));const safe={...health,meals:arr(health.meals),water:arr(health.water),reminderChecks:arr(health.reminderChecks),dailyNotes:arr(health.dailyNotes)},w=model.weeklySummary(safe);return shell('7 日合成回顾',`${date(w.from)} 至 ${date(w.to)} · 不是医疗报告`,card(`<div class="hig-stats">${stat('记录天数',fmt(w.recordedDays)+'/7','天')}${stat('餐食条目',fmt(w.mealCount),'条')}${stat('热量有值',fmt(w.knownMeals)+'/'+fmt(w.mealCount),'条')}</div><h3>已填演示热量合计</h3>${stat('已知小计',fmt(w.kcal),'kcal','缺值未当作 0；不代表完整全天摄入')}`)+card(`<ul class="hig-list"><li>饮水演示合计<strong>${fmt(w.waterMl)} ml</strong></li><li>提醒打卡<strong>${fmt(w.checkCount)} 次</strong></li><li>日常自述<strong>${fmt(w.dailyCount)} 条</strong></li></ul>`)+note(w.limits||'仅汇总合成记录，未记录不代表未发生。')+`<div class="hig-actions">${button('餐食明细','records')}${button('指标趋势','metrics')}${button('日常自述','daily')}</div>`);}
function recipeArt(r){const src=Object.prototype.hasOwnProperty.call(art,r.id)?art[r.id]:null;return `<div class="hig-recipe-art"><span class="hig-recipe-art-fallback" aria-hidden="true">${esc(r.emoji||'🍽')}</span>${src?`<img data-recipe-art="${esc(r.id)}" src="${src}" alt="${esc(r.name)} · AI 原创示意图，非实拍" loading="lazy" width="1254" height="1254">`:''}</div>`;}
function selections(health,recipes){const ids=Array.isArray(health.recipeSelections)?[...new Set(health.recipeSelections.filter(x=>typeof x==='string'))]:[];return {ids,known:recipes.filter(r=>ids.includes(r.id)),unknown:ids.filter(id=>!recipes.some(r=>r.id===id))};}
function renderRecipes({health={},model={}}={}){const recipes=arr(model.RECIPES),s=selections(health,recipes);return shell('通用食谱','发现做法，先核对食材与限制。',note('通用合成示例 · 未接个性化评估；选择食谱不等于进食，不写入饮食记录。')+`<div class="hig-section-title"><h3>食谱 · ${recipes.length} 道</h3><span>备选 ${s.known.length} 道${s.unknown.length?' · 另有 '+s.unknown.length+' 项无法匹配':''}</span></div><div class="hig-recipe-grid">${recipes.map(r=>`<button type="button" class="hig-recipe" data-hd="recipe" data-id="${esc(r.id)}">${recipeArt(r)}<div><strong>${esc(r.name)}</strong><small>${esc(r.category||'分类未提供')} · ${fmt(r.minutes)} 分钟</small><span class="hig-pill">${s.ids.includes(r.id)?'已加入备选':'查看做法'}</span><small>份量与营养数值未提供</small></div></button>`).join('')}</div>${recipes.length?'':note('暂无可用食谱。')}<p class="hig-muted">AI 原创示意图，非实拍；不能据图判断份量、营养或实际熟度。</p>`+renderSelections({health,model,embedded:true}));}
function renderRecipe({health={},model={},recipeId}={}){const r=arr(model.RECIPES).find(x=>x.id===recipeId);if(!r)return shell('食谱暂不可用','没有匹配的当前食谱',note('请返回列表重新选择，未新增任何记录。'));const selected=selections(health,[r]).ids.includes(r.id);return shell(r.name,'通用合成做法，不是个性化饮食方案。',recipeArt(r)+card(`<div class="hig-section-title"><h3>${esc(r.name)}</h3><span class="hig-pill">${esc(r.category||'分类未知')}</span></div><p>${fmt(r.minutes)} 分钟 · AI 原创示意图，非实拍</p><div class="hig-stats">${stat('份量','未知','')}${stat('能量','未知','kcal')}${stat('营养数据','未提供','')}</div>`)+card(`<h3>食材</h3><ul class="hig-ingredients">${(Array.isArray(r.ingredients)?r.ingredients:[]).map(v=>`<li>${esc(v)}<small>用量未提供</small></li>`).join('')}</ul>`)+note(`已知食材过敏原：${Array.isArray(r.allergens)&&r.allergens.length?r.allergens.join('、'):'未列出；不表示无过敏原'}。调味料及交叉接触需另行核对。`)+card(`<h3>制作步骤</h3><ol class="hig-steps">${(Array.isArray(r.steps)?r.steps:[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`)+note('选择只加入本机演示备选，不增加进食记录；未提供可编辑周计划。')+button(selected?'已加入备选':'加入下餐备选','select-recipe',r.id,selected?' disabled aria-disabled="true"':''));}
function renderSelections({health={},model={},embedded=false}={}){const s=selections(health,arr(model.RECIPES)),body=card(`<h3>下餐备选 · ${s.known.length} 道</h3>${s.known.length?`<ul class="hig-list">${s.known.map(r=>`<li><strong>${esc(r.name)}</strong>${button('查看做法','recipe',r.id)}</li>`).join('')}</ul>`:note('尚未选择食谱。')}${s.unknown.length?note(`${s.unknown.length} 项选择无法匹配当前食谱，未计入上方菜谱数。`):''}<p class="hig-muted">这里不是周计划或已吃清单。没有日期、餐次、份量和营养计算契约，不生成虚构日程或摄入合计。</p>`);return embedded?body:shell('下餐备选','选择与进食分开记录。',body);}
return Object.freeze({renderMetrics,renderConditions,renderWeekly,renderRecipes,renderRecipe,renderSelections});
});
